using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: EF 9 renamed "Discriminator" to "$type".
        // Existing documents use "Discriminator", so preserve the old property name.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: EF 9 changed id format from "EntityType|Key" to just "Key".
        // Existing documents use "Blog|1" format, so opt back in to the legacy format.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .HasJsonPropertyName("id");
        modelBuilder.Entity<Blog>().UsePropertyAccessMode(PropertyAccessMode.Property);

        // Breaking change 3: Cosmos DB provider no longer supports sync I/O by default.
        // (Handled in SyncJob.cs by switching to async calls.)

        // Note: HasIndex is not supported on Cosmos — removed.
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // If sync calls are still needed anywhere, opt back in explicitly:
        // optionsBuilder.UseCosmos(...).ConfigureWarnings(w => w.Ignore(CosmosEventId.SyncNotSupported));
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

